def paginate(items,page,size):
    pages = max(1, page)
    if page > max(1, len(items) - 1) or size <= 0:
        return {
            "items": items if len(items) == 0 else [],
            "total": len(items),
            "pages": 0,
        }
    items_list = items[:]
    for p in range(pages):
        idx = p * size
        end = min(idx + size, len(items_list))
        items_list = items_list[idx:end]
    return {
        "items": items_list,
        "total": len(items_list),
        "pages": pages,
    }

